import{_ as s,a0 as a,w as u,s as p,ao as n,I as o,a1 as t,A as r,x as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"5 個用於 SOHO 的 Linux 服務器發行版 | LCTT x X-CMD","titleTemplate":false,"description":"5 個用於 SOHO 的 Linux 服務器發行版 | LCTT (201901) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"5 個用於 SOHO 的 Linux 服務器發行版 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"5 個用於 SOHO 的 Linux 服務器發行版 | LCTT (201901) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201901/20190118 Top 5 Linux Server Distributions","title":"5 個用於 SOHO 的 Linux 服務器發行版","tag":"201901","desc":""},"relativePath":"201901/20190118 Top 5 Linux Server Distributions.md","filePath":"[post].md"}'),d={name:"201901/20190118 Top 5 Linux Server Distributions.md"};function S(m,l,f,x,w,b){const i=a("Link");return u(),p("div",null,[l[35]||(l[35]=n('<h1 id="_5-個用於-soho-的-linux-服務器發行版" tabindex="-1">5 個用於 SOHO 的 Linux 服務器發行版 <a class="header-anchor" href="#_5-個用於-soho-的-linux-服務器發行版" aria-label="Permalink to “5 個用於 SOHO 的 Linux 服務器發行版”">​</a></h1><blockquote><p>Jack Wallen 為 Linux 服務器發行版提供了一些可靠的選擇，絕對值回票價。</p></blockquote><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/rockstor-main.jpg?itok=VNvfEIlf" alt=""></p><p>啊，這個古老的問題：哪種 Linux 發行版最適合做服務器？通常，問這種問題時，所浮現出來的標準的答覆就是：</p><ul><li>RHEL</li><li>SUSE</li><li>Ubuntu 服務器</li><li>Debian</li><li>CentOS</li></ul><p>然而，假如你將眼界放得更寬（不將服務器只看做是 IDC 託管的那種互聯網服務器時），可能答案會有點不同。我準備稍微來點不同的。我想做出一個滿足入選標準的發行版列表，這些發行版不僅是優秀的候選者，而且易於使用，可以為你的業務中的許多功能提供服務。在某些情況下，我選擇的是一些替代品，可以取代其它需要一些工作才能達成要求的操作系統。</p><p>我的一些選擇是企業級服務器的社區版本，它們可以被視為購買更強大平台的入門級產品。你甚至可以在這裏找到一兩個作為特定任務平台的候選者。然而，最重要的是，你在此列表中找到的並非尋常的泛泛之輩。</p><h3 id="clearos" tabindex="-1">ClearOS <a class="header-anchor" href="#clearos" aria-label="Permalink to “ClearOS”">​</a></h3><p>什麼是 ClearOS？對於家庭和小型企業用途，你可能找不到比它更好的解決方案。ClearOS 開箱即用，包括了入侵檢測、強大的防火牆、帶寬管理工具、郵件服務器、域控制器等工具。其目的是將服務器作為一個簡單的家庭和 SOHO 服務器，並具有用户友好的基於 Web 的圖形化界面，這使得 ClearOS 在某些評比中脱穎而出。從其界面中，你可以找到一個應用程序市場（圖 1），其中包含數百個應用程序（其中一些是免費的，而另一些則具有相關費用），這使得擴展 ClearOS 功能集非常容易。換句話説，你可以將 ClearOS 作為你的家庭和小型企業所需的平台。最重要的是，與許多其他替代方案不同，你只需支付所需的軟件和支持。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/clearos.jpg?itok=knQkn5ch" alt=""></p><p><em>圖 1：ClearOS 應用程序市場</em></p><p>有三種版本的 ClearOS：</p>',12)),o("ul",null,[o("li",null,[t(i,{href:"https://www.clearos.com/clearfoundation/software/clearos-7-community"},{default:r(()=>[...l[0]||(l[0]=[e("ClearOS Community",-1)])]),_:1}),l[1]||(l[1]=e(" - 免費版 ClearOS",-1))]),o("li",null,[t(i,{href:"https://www.clearos.com/products/clearos-editions/clearos-7-home"},{default:r(()=>[...l[2]||(l[2]=[e("ClearOS Home",-1)])]),_:1}),l[3]||(l[3]=e(" - 適於家庭辦公",-1))]),o("li",null,[t(i,{href:"https://www.clearos.com/products/clearos-editions/clearos-7-business"},{default:r(()=>[...l[4]||(l[4]=[e("ClearOS Business",-1)])]),_:1}),l[5]||(l[5]=e(" - 適於小型企業，包括了付費支持。",-1))])]),l[36]||(l[36]=n('<p>為了使軟件安裝更加容易，ClearOS 應用市場允許你通過以下方式進行選擇軟件：</p><p>* 按功能（根據任務顯示應用程序）    * 按類別（顯示相關應用程序組）    * 快速選擇文件（允許你按預先配置的模板選擇，以幫助你快速啓動和運行）</p><p>換句話説，如果你正在尋找 Linux 的家庭、SOHO 或 SMB 服務器，ClearOS 是一個出色的選擇（特別是如果你沒有啓動和運行標準的 Linux 服務器的能力時）。</p><h3 id="fedora-服務器" tabindex="-1">Fedora 服務器 <a class="header-anchor" href="#fedora-服務器" aria-label="Permalink to “Fedora 服務器”">​</a></h3><p>你肯定聽説過 Fedora Linux。它是市場上最好的前沿發行版之一。但是你知道這個出色的 Fedora 桌面發行版的開發者們也開發了服務器版嗎？Fedora 服務器平台是一個短生命週期的、社區支持的服務器操作系統。這使得經驗豐富的、或對任何類型的 Linux（或任何操作系統）有經驗的系統管理員，可以使用開源社區中提供的最新技術。在這段描述中有三個關鍵詞：</p><ul><li>經驗豐富</li><li>系統</li><li>管理員</li></ul><p>換言之，新用户就不要考慮了。雖然 Fedora 服務器完全能夠處理你拋出的任何任務，但它需要一些擁有更多的 Linux 功夫的人來使它工作並且運行良好。Fedora 服務器非常好的一點是，開箱即用，它包括了市場上用於服務器的開源的基於 Web 的最好的界面之一。通過 Cockpit（圖 2），你可以快速瀏覽系統資源、日誌、存儲、網絡以及擁有管理帳户、服務、應用程序和更新的能力。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/fedoraserver.jpg?itok=phaAIRXW" alt="Fedora Server" title="Fedora Server"></p><p><em>圖 2：運行在 Fedora 服務器上的 Cockpit</em></p><p>如果你可以使用最前沿的軟件，並想要一個出色的管理儀表板，Fedora 服務器可能就是你要的平台。</p><h3 id="nethserver" tabindex="-1">NethServer <a class="header-anchor" href="#nethserver" aria-label="Permalink to “NethServer”">​</a></h3><p>正如你所發現的那樣，NethServer 是每個人都知道的簡單 SMB Linux 服務器。通過 NethServer 的最新版本，你的小型企業將得到：</p><ul><li>內置 Samba 活動目錄控制器    * 與 Nextcloud 的無縫集成    * 證書管理    * HTTPS 透明代理    * 防火牆    * 郵件服務器和過濾器    * Web 服務器和過濾器    * 羣件    * IPS / IDS 或 VPN</li></ul><p>所有包含的功能都可以通過用户友好的基於 Web 的界面輕鬆配置，包括單擊安裝模組以擴展 NethServer 功能集（圖 3）。NethServer 與 ClearOS 的區別在於它的設計目的是使管理工作更輕鬆。換句話説，這個平台提供了更多的靈活性和功能。與面向家庭辦公室和 SOHO 部署的 ClearOS 不同，NethServer 在小型商業環境中用起來就像在家庭裏使用一樣方便。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/nethserver.jpg?itok=HO-CRbOV" alt="NethServer" title="NethServer"></p><p><em>圖 3：給 NethServer 添加模組</em></p><h3 id="rockstor" tabindex="-1">Rockstor <a class="header-anchor" href="#rockstor" aria-label="Permalink to “Rockstor”">​</a></h3><p>Rockstor 是採用 Linux 和 Btfrs 的高級網絡附加存儲（NAS）和雲存儲服務器，可部署用於家庭、SOHO 以及中小型企業。藉助 Rockstor，你可以獲得一個完整的 NAS /雲解決方案，其中包含一個用户友好的基於 Web 的 GUI 工具，管理員可以像普通用户一樣輕鬆使用它來設置。一旦部署好了 Rockstor，你就可以創建存儲池、共享、快照、管理複製和用户、共享文件（藉助 Samba、NFS、SFTP 和 AFP），甚至擴展它的功能集，這要歸功於附加組件（稱為 Rock-ons）。Rock-ons 列表包括：</p><ul><li>CouchPotato（Usenet 和 BitTorrent 用户的下載器）</li><li>Deluge（BitTorrent 用户的電影下載器）</li><li>EmbyServer（Emby 媒體服務器）</li><li>Ghost（專業博主的發佈平台）</li><li>GitLab CE（Git 倉庫託管和協作）</li><li>Gogs Go Git Service（輕量級 Git 版本控制服務器和前端）</li><li>Headphones（NZB 和 Torrent 的音樂自動下載器）</li><li>用於 Squeezebox 設備的羅技 Squeezebox 服務器</li><li>MariaDB（關係型數據管理系統）</li><li>NZBGet（高效的 usenet 下載器）</li><li>OwnCloud-Official（安全的文件共享和託管）</li><li>Plexpy（基於 Python 的 Plex 用量跟蹤器）</li><li>Rocket.Chat（開源聊天平台）</li><li>SaBnzbd（Usenet 下載器）</li><li>Sickbeard（用於電視節目的互聯網個人視頻錄像機）</li><li>Sickrage（電視節目的自動視頻庫管理器）</li><li>Sonarr（Usenet 和 BitTorrent 用户的個人視頻錄像機）</li><li>Symform（備份設備）</li></ul><p>Rockstor 還包括了一目瞭然的儀表板，使管理員可以快速訪問他們所需的有關其服務器的所有信息（圖 4）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/rockstore.jpg?itok=EN_5oFxQ" alt="Rockstor" title="Rockstor"></p><p><em>圖 4： Rockstor 面板</em></p><h3 id="zentyal" tabindex="-1">Zentyal <a class="header-anchor" href="#zentyal" aria-label="Permalink to “Zentyal”">​</a></h3><p>Zentyal 是另一個小型企業服務器，可以很好地處理多個任務。如果你正在尋找可以處理以下內容的 Linux 發行版：</p><ul><li>目錄和域服務器</li><li>郵件服務器</li><li>網關</li><li>DHCP、DNS 和 NTP 服務器</li><li>認證機構（CA）</li><li>VPN</li><li>實時消息（IM）</li><li>FTP 服務器</li><li>反病毒</li><li>SSO 認證</li><li>文件共享</li><li>RADIUS 認證</li><li>虛擬化管理</li><li>等等</li></ul><p>Zentyal 可能是你的新選擇。從 2004 年 Zentyal 就存在了，它基於 Ubuntu Server，因此它擁有堅實的基礎和豐富的應用程序。在 Zentyal 儀表板的幫助下（圖 5），管理員可以輕鬆管理：</p><ul><li>系統</li><li>網絡</li><li>日誌</li><li>軟件更新和安裝</li><li>用户/組</li><li>域</li><li>文件共享</li><li>郵件</li><li>DNS</li><li>防火牆</li><li>證書</li><li>等等</li></ul><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/zentyal.jpg?itok=Un9lpgh6" alt=""></p><p><em>圖 5：Zentyal 儀表板</em></p><p>向 Zentyal 服務器添加新組件只需要打開儀表板，單擊“軟件管理” -&gt; “Zentyal 組件”，選擇要添加的組件，然後單擊安裝。Zentyal 可能會遇到的一個問題是，它提供不了與 Nethserver 和 ClearOS 一樣多的插件。但它提供的服務，則做得非常好。</p><h3 id="更多來自於" tabindex="-1">更多來自於 <a class="header-anchor" href="#更多來自於" aria-label="Permalink to “更多來自於”">​</a></h3>',31)),o("p",null,[l[11]||(l[11]=e("這個 Linux 服務器列表顯然不是詳盡無遺的。然而，這是一種對你可能沒有聽説過的五大服務器發行版的獨特視角。當然，如果你更願意使用更傳統的 Linux 服務器發行版，你可以隨時堅持使用 ",-1)),t(i,{href:"https://www.centos.org/"},{default:r(()=>[...l[6]||(l[6]=[e("CentOS",-1)])]),_:1}),l[12]||(l[12]=e("、",-1)),t(i,{href:"https://www.ubuntu.com/download/server"},{default:r(()=>[...l[7]||(l[7]=[e("Ubuntu 服務器",-1)])]),_:1}),l[13]||(l[13]=e("、",-1)),t(i,{href:"https://www.suse.com/"},{default:r(()=>[...l[8]||(l[8]=[e("SUSE",-1)])]),_:1}),l[14]||(l[14]=e("、",-1)),t(i,{href:"https://www.redhat.com/en/technologies/linux-platforms/enterprise-linux"},{default:r(()=>[...l[9]||(l[9]=[e("RHEL",-1)])]),_:1}),l[15]||(l[15]=e(" 或 ",-1)),t(i,{href:"https://www.debian.org/"},{default:r(()=>[...l[10]||(l[10]=[e("Debian",-1)])]),_:1}),l[16]||(l[16]=e("……它們大多都出現在市場上最好的服務器發行版列表中。但是，如果你正在尋找一些不同的東西，那麼試試這五個發行版中的一個。",-1))]),o("p",null,[l[18]||(l[18]=e("通過 Linux 基金會和 edX 的免費",-1)),t(i,{href:"https://training.linuxfoundation.org/linux-courses/system-administration-training/introduction-to-linux"},{default:r(()=>[...l[17]||(l[17]=[e("“Linux 簡介”",-1)])]),_:1}),l[19]||(l[19]=e("課程瞭解有關 Linux 的更多信息。",-1))]),l[37]||(l[37]=o("hr",null,null,-1)),o("p",null,[l[21]||(l[21]=e("via: ",-1)),t(i,{href:"https://www.linux.com/blog/learn/2019/1/top-5-linux-server-distributions"},{default:r(()=>[...l[20]||(l[20]=[e("https://www.linux.com/blog/learn/2019/1/top-5-linux-server-distributions",-1)])]),_:1})]),o("p",null,[l[26]||(l[26]=e("作者：",-1)),t(i,{href:"https://www.linux.com/users/jlwallen"},{default:r(()=>[...l[22]||(l[22]=[e("Jack Wallen",-1)])]),_:1}),l[27]||(l[27]=e(" 選題：",-1)),t(i,{href:"https://github.com/lujun9972"},{default:r(()=>[...l[23]||(l[23]=[e("lujun9972",-1)])]),_:1}),l[28]||(l[28]=e(" 譯者：",-1)),t(i,{href:"https://github.com/wxy"},{default:r(()=>[...l[24]||(l[24]=[e("wxy",-1)])]),_:1}),l[29]||(l[29]=e(" 校對：",-1)),t(i,{href:"https://github.com/wxy"},{default:r(()=>[...l[25]||(l[25]=[e("wxy",-1)])]),_:1})]),o("p",null,[l[32]||(l[32]=e("本文由 ",-1)),t(i,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...l[30]||(l[30]=[e("LCTT",-1)])]),_:1}),l[33]||(l[33]=e(" 原創編譯，",-1)),t(i,{href:"https://linux.cn/"},{default:r(()=>[...l[31]||(l[31]=[e("Linux中國",-1)])]),_:1}),l[34]||(l[34]=e(" 榮譽推出",-1))])])}const T=s(d,[["render",S]]);export{k as __pageData,T as default};
